// Reserved marks of runtime-written knowledge: the compaction summaries of endless chats
// (context/compact.ts writes them, context/observations.ts reads them and shows them to every
// agent of the chat as "generated by the runtime").
// Owns: recognising such rows and dropping the reserved tag where the marks do not fit.
// Never: decides who may write – agent tools refuse (tools/builtin/memory.ts), the store only
// normalizes tags.

import type { KnowledgeItem } from '../../shared/model/knowledge.ts';

export const COMPACTION_TAG = 'compaction';

const isReserved = (tag: string): boolean => tag.trim().toLowerCase() === COMPACTION_TAG;

/** A runtime compaction summary (or a row that claims to be one): agents must not rewrite it. */
export function isCompactionSummary(item: Pick<KnowledgeItem, 'kind' | 'tags' | 'source'>): boolean {
  return item.kind === 'observation' && item.source.trusted === true && item.tags.some(isReserved);
}

/** Tags of a row an agent writes itself: the reserved compaction mark is removed. */
export function agentTags(tags: readonly string[]): string[] {
  return tags.filter((tag) => !isReserved(tag));
}

/**
 * Store-side normalization: the compaction tag stays only on an observation that carries the
 * full marks of a runtime summary (scope 'conversation', trusted agent source whose ref is that
 * chat – see context/observations.ts observationSource).
 */
export function normalizeReservedTags(item: Pick<KnowledgeItem, 'kind' | 'scope' | 'scopeId' | 'source' | 'tags'>): string[] {
  if (item.kind !== 'observation' || !item.tags.some(isReserved)) return item.tags;
  const source = item.source;
  const runtime = item.scope === 'conversation' && source.kind === 'agent' && source.trusted === true && !!item.scopeId && source.ref === item.scopeId;
  return runtime ? item.tags : agentTags(item.tags);
}
